// CSD_RATIONALE_BEGIN
// Root cause of 46.7% wrong answers (all syntax-valid): The model generates
// semantically incorrect SQL in three dominant patterns observed in rollouts:
//   (1) Extra-column insertion: "SELECT name, age, hometown" instead of "SELECT age, hometown"
//   (2) Wrong aggregation: COUNT(*) with WHERE instead of COUNT(DISTINCT col)
//   (3) Repetition/hallucination: "AND countrycode = ..." repeated 20+ times
// Architecture (phases 1-4) is sound — 300/300 have constrained activity and
// correct syntax. The gap to 66.3% is purely semantic.
//
// Primary fix: Replace the vague guidance string with a concrete, Spider-specific
// instruction that directly targets the three observed failure modes:
//   - "select ONLY requested columns" → prevents extra-column insertion
//   - "COUNT(DISTINCT x) for unique value counts" → fixes aggregation errors
//   - "use INTERSECT for both-Y-and-Z on same attribute" → fixes set logic
//   - "do not repeat conditions" → prevents hallucination loops
//
// Secondary fix: Reduce CloseSpanWithinBudget budget from 400 to 250.
// The 400-token budget allowed the 389-token repetition failure (example 3).
// 250 tokens still accommodates full WHERE/JOIN/GROUP BY/ORDER BY SQL,
// and prevents runaway repetition. Budget math: 5 (preamble) + 1 (force-<<) +
// 250 (SQL gen) = 256 << 900.
//
// The longest-complete-prefix tracking in CloseSpanWithinBudget is preserved —
// it finds the best complete SQL including WHERE clauses rather than stopping
// at the first valid (but truncated) SELECT-FROM parse.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard contains !insideConstrainedOut, so the
//   implication is vacuous on every iteration. The only true-flip is via
//   RenderedEndsWith("<<"), at which point we set currentConstrainedOut := [];
//   IsValidPrefix([]) holds by the method precondition. EOS break leaves
//   insideConstrainedOut false (still vacuous).
//
// Phase 2 OpenConstrainedSpan: Executes only when !insideConstrainedOut.
//   Postcondition sets insideConstrainedOut := true, currentConstrainedOut := [].
//   IsValidPrefix([]) holds by precondition. Invariant satisfied.
//
// Phase 3 CloseSpanWithinBudget: The helper's postcondition directly guarantees
//   (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)).
//   Both closed and open-span exit paths are covered.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs 1 step. On EOS path: no append, steps+1,
//   bound preserved. On non-EOS path: |generated| += 1, steps += 1 (1:1 ratio).
//   RenderedEndsWith branch only updates span state, not generated length.
//   Invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan appends exactly "<<" (1 token), steps += 1.
//   Bound preserved at exact 1:1 ratio.
//
// Phase 3: closeBudget = min(maxSteps - steps_before, 250) ≤ maxSteps - steps_before.
//   CloseSpanWithinBudget postcondition: |cg| ≤ |generated| + closeBudget.
//   We assign steps += closeBudget, so |generated| ≤ |generatedPrefix| + steps. ✓
//   Tokens consumed by dead-end avoidance or EOS that are not appended visibly
//   still count against closeBudget, so visible output growth ≤ closeBudget.
//
// cost = steps ≤ maxSteps: closeBudget ≤ maxSteps - steps_before ensures
//   steps_before + closeBudget ≤ maxSteps. Phase 1 guard (steps < maxSteps)
//   and Phase 2 guard (steps < maxSteps) each enforce a similar bound.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a minimal and correct SQL query. Rules: (1) SELECT only the columns explicitly named in the question; do NOT add columns like 'name' or 'id' unless the question asks for them. (2) When a question asks for items satisfying BOTH condition A and condition B where A and B are values of the same column (e.g. 'use both English and Dutch'), use INTERSECT subqueries rather than AND. (3) Use COUNT(DISTINCT col) when counting unique or distinct values. (4) Do not repeat WHERE conditions. Use exact table and column names from the schema.");

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (at most 5 steps) to let model emit "SQL: <<"
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if the model did not emit it naturally
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3+4 combined: Generate full SQL query and close span.
// CloseSpanWithinBudget tracks the LONGEST complete parse prefix (not the first),
// ensuring WHERE/JOIN/GROUP BY/ORDER BY clauses are included when the model
// generates them. Budget=250 prevents runaway repetition while still allowing
// full multi-clause SQL (observed avg ~30 constrained tokens/example).
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 250 {
    closeBudget := remaining;
  } else {
    closeBudget := 250;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

